contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint128 vBaseBefore = c.virtualBaseTokenReserves();
        uint128 vNftBefore = c.virtualNftReserves();
        uint16 feeRateBefore = c.feeRate();

        address(this).call(abi.encodeWithSignature("transferFrom(address,address,uint256)", address(this), address(c), uint256(1)));

        assert(c.virtualBaseTokenReserves() == vBaseBefore && c.virtualNftReserves() == vNftBefore && c.feeRate() == feeRateBefore);
    }

    receive() external payable {}
}

