contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address baseToken,
        address nft,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public payable {
        require(baseToken == address(0), "only ETH pool");
        c.initialize(
            baseToken,
            nft,
            vBase,
            vNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoyalties
        );

        uint128 beforeBase = c.virtualBaseTokenReserves();
        uint128 beforeNft = c.virtualNftReserves();
        uint256 p = c.price();

        assert(p == (uint256(beforeBase) * 10**18) / uint256(beforeNft));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate) public {
        require(vNft > 0, "zero nft reserves");
        require(feeRate <= 5000, "fee too high");
        c.initialize(address(0), address(0), vBase, vNft, changeFee, feeRate, bytes32(0), false, false);

        uint128 beforeBase = c.virtualBaseTokenReserves();
        uint128 beforeNft = c.virtualNftReserves();
        uint256 p = c.price();

        assert(p == (uint256(beforeBase) * 1e18) / uint256(beforeNft));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint128 vBase, uint128 vNft) public {
        require(vBase <= 1e6, "vBase too large");
        require(vNft > vBase * 1e12, "ratio too small");
        require(vNft <= 2e18, "vNft too large");
        c.initialize(address(0), address(0), vBase, vNft, 0, 0, bytes32(0), false, false);
        uint256 expected = (uint256(vBase) * 1e18) / uint256(vNft);
        uint256 actual = c.price();
        assert(actual == expected);
    }
}
